#define AGENT_TRACE_OK 1
#define AGENT_TRACE_FAIL 2
#define AGENT_TRACE_TIMEOUT 3

typedef struct {
    char run_id[17]; /* 16 hex chars + NUL */
    char chat_id[64];
    char channel[16];
