{
    struct timeval tv;

    gettimeofday(&tv, NULL);
    t->status = status;

    uint32_t elapsed = (uint32_t)tv.tv_sec - t->start_ts;

    syslog(LOG_INFO,
        "[%s:%s] END status=%s iters=%d tools=%d "
        "llm_ms=%u elapsed=%us backend=%d",
        TAG, t->run_id, status_str(status),
