/* Host stubs for vela_tls.c symbols that only exist on the board. */

#include <stddef.h>
#include <string.h>

int agent_secure_random(unsigned char* output, size_t len)
{
    memset(output, 0x5a, len);
    return 0;
}

/* Direct connection, no CONNECT proxy. */

int http_proxy_is_enabled(void)
{
    return 0;
}

int proxy_open_tunnel(const char* host, int port, int timeout_ms)
{
    (void)host;
    (void)port;
    (void)timeout_ms;
    return -1;
}

/* Drives the real vela_https_request_timed() against the local test server.
 *
 * Each case prints the phases the firmware recorded, plus the wall time the
 * client spent.  A client that detects the end of the body returns right
 * after the last byte; one that does not sits until the socket timeout, and
 * that difference is the defect under test.
 */

#include "infra/vela_tls.h"

#include <stdio.h>
#include <string.h>
#include <time.h>

static double now_s(void)
{
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
}

static void run(const char* path, int expect_complete)
{
    char resp[4096];
    size_t body_len = 0;
    agent_llm_timing_t timing;
    double t0;
    double elapsed;
    int status;

    agent_timing_reset(&timing);

    t0 = now_s();
    status = vela_https_request_timed("127.0.0.1", "9443", "POST", path, NULL,
        "{\"probe\":1}", 11, resp, sizeof(resp), &body_len, &timing);
    elapsed = now_s() - t0;

    printf("%-22s status=%-4d wall=%6.2fs ttfb=%-5d body=%-5d http=%-5d "
           "req=%u len=%zu\n",
        path, status, elapsed, timing.ttfb_ms, timing.body_ms,
        timing.http_total_ms, timing.unsigned_req(), body_len);

    /* A complete response must return well before the 5 s socket timeout the
     * host build was compiled with.  An unframed keep-alive reply cannot, and
     * that is expected rather than a failure. */

    if (expect_complete) {
        if (elapsed > 3.0) {
            printf("  FAIL: returned after %.2fs, the body end was not "
                   "detected\n", elapsed);
        } else {
            printf("  ok: body end detected, no extra wait\n");
        }
    } else {
        printf("  note: unframed keep-alive; waiting is unavoidable\n");
    }

    /* Body content sanity: the client must not hand back chunk framing. */

    if (body_len > 0 && strstr(resp, "\r\n") != NULL
        && expect_complete) {
        printf("  FAIL: response still contains chunk framing: %.40s\n", resp);
    }
}

int main(void)
{
    printf("== RSP-01 body framing acceptance ==\n");
    run("/content-length", 1);
    run("/chunked", 1);
    run("/chunked-pieces", 1);
    run("/close", 1);
    run("/truncated-cl", 0);
    run("/truncated-chunked", 0);
    run("/unframed-keepalive", 0);
    return 0;
}

