/* ── Deterministic single-point reply ──────────────────────── */

/* A question like "what is the UPS load" costs two LLM round-trips: one to
 * pick vg_point_read and one to restate the number the tool already
 * returned.  The second call exists only to reword a value that is already
 * decided, and it carries the same multi-second server wait as the first.
 *
 * The tool output is machine-formatted by vg_agent_query_format_point():
 *
 *   vgquery: point id=ups_load name=UPS负载 value=42 unit=% ok=1 age_ms=900
 *
 * so the fields can be rendered here without guessing.  Only that exact
 * shape is handled.  Anything else - ambiguity, no table, no sample, a read
 * failure, stale data, thresholds needing interpretation - falls through to
 * the LLM as before, because those cases need wording rather than echoing.
 *
 * Returns a heap string, or NULL when the LLM must handle the reply. */

static char* format_point_reply(const char* tool_output)
{
    const char* id;
    const char* name;
    const char* value;
    const char* unit;
    const char* ok;
    const char* age;
    const char* stale;
    char out[256];
    int n;

    if (tool_output == NULL
        || strncmp(tool_output, "vgquery: point ", 15) != 0) {
        return NULL;
    }

    /* Every one of these must be present: a reply built from a partial line
     * would state a value without saying how old it is. */

    id = strstr(tool_output, " id=");
    name = strstr(tool_output, " name=");
    value = strstr(tool_output, " value=");
    unit = strstr(tool_output, " unit=");
    ok = strstr(tool_output, " ok=");
    age = strstr(tool_output, " age_ms=");

    if (!id || !name || !value || !unit || !ok || !age) {
        return NULL;
    }

    /* Only a successful read with a sample is echoed.  read_failed and
     * no_sample carry reasons the user needs explained, not repeated. */

    if (strncmp(ok, " ok=1", 5) != 0) {
        return NULL;
    }

    stale = strstr(tool_output, " stale=1");

    char id_buf[64], name_buf[96], value_buf[32], unit_buf[16];
    unsigned long age_ms = 0;

    if (sscanf(id, " id=%63s", id_buf) != 1
        || sscanf(name, " name=%95s", name_buf) != 1
        || sscanf(value, " value=%31s", value_buf) != 1
        || sscanf(unit, " unit=%15s", unit_buf) != 1
        || sscanf(age, " age_ms=%lu", &age_ms) != 1) {
        return NULL;
    }

    /* The value is echoed exactly as the tool produced it.  No rounding, no
     * unit conversion, no recomputation: this path exists to remove a model
     * round-trip, not to become a second source of truth. */

    n = snprintf(out, sizeof(out), "%s 当前读数 %s %s",
        strcmp(name_buf, "-") != 0 ? name_buf : id_buf,
        strcmp(value_buf, "-") != 0 ? value_buf : "无有效读数",
        strcmp(unit_buf, "-") != 0 ? unit_buf : "");

    if (n < 0 || (size_t)n >= sizeof(out)) {
        return NULL;
    }

    if (stale != NULL) {
        snprintf(out + n, sizeof(out) - (size_t)n,
            "，采样已过期（%.0f 秒前）", (double)age_ms / 1000.0);
    } else {
        snprintf(out + n, sizeof(out) - (size_t)n,
            "（%.0f 秒前采样）", (double)age_ms / 1000.0);
    }

    syslog(LOG_INFO,
        "[%s] point reply rendered from tool output, skipping LLM round\n",
        TAG);
    return strdup(out);
}

